//! `rok sqlc init --template <NAME>`: copies a ready-made project, a
//! directory the `rok-templates` crate embeds, into a project, each file
//! only when absent. The template names, their manifests and the file
//! plan are rok-templates' catalog (workspace ADR 0027); this module keeps
//! the write policy: rok-data-sqlc's generated files
//! (`@generated by rok-data-sqlc` on their first line) are left out — `rok
//! sqlc generate` writes them — and other files, such as the template's
//! pinned `Cargo.lock`, are copied. Adding a file to a template's
//! directory (in `rok-templates`) is all it takes to ship it.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result, bail};

use super::{Scaffolded, crate_name, declared_crate, is_cargo_default_main};
use rok_templates::File;
use rok_templates::catalog;
use rok_templates::names::{DEFAULT_ORG, Names};
use rok_templates::rename::Renames;

use crate::output::write_absent;
use crate::report::display_path;

/// The names `--template` takes: the catalog's (workspace ADR 0027).
pub fn names() -> impl Iterator<Item = &'static str> {
    catalog::names()
}

/// The embedded files of the template `name`.
fn files(name: &str) -> Result<&'static [File]> {
    match catalog::files(name) {
        Some(files) => Ok(files),
        None => bail!(
            "unknown template `{name}`; the templates are: {}",
            catalog::names().collect::<Vec<_>>().join(", ")
        ),
    }
}

/// rok-data-sqlc's generated marker, in any comment syntax.
const GENERATED_MARKER: &str = "@generated by rok-data-sqlc";

/// The marker files generated when the crate was published as `rok-sqlc`.
/// Shipped templates hold files generated before the rename; existing
/// projects keep working, and `init` still leaves them out.
const LEGACY_GENERATED_MARKER: &str = "@generated by rok-sqlc";

/// Whether `text` is one of rok-data-sqlc's generated files: one of
/// [`GENERATED_MARKER`] or [`LEGACY_GENERATED_MARKER`] on its first line.
/// Other tools' generated files (cargo's `Cargo.lock`) are not.
fn is_generated(text: &str) -> bool {
    text.lines().next().is_some_and(|line| {
        line.contains(GENERATED_MARKER) || line.contains(LEGACY_GENERATED_MARKER)
    })
}

/// `text` with each path through the crate `from` (`from::` as a whole path
/// segment) through `to` instead. `my_from::` names another crate and stays.
fn rename_crate(text: &str, from: &str, to: &str) -> String {
    let pattern = format!("{from}::");
    let mut renamed = String::with_capacity(text.len());
    let mut copied = 0;
    for (at, _) in text.match_indices(&pattern) {
        let starts_segment = !text[..at]
            .chars()
            .next_back()
            .is_some_and(|c| c.is_alphanumeric() || c == '_');
        if starts_segment {
            renamed.push_str(&text[copied..at]);
            renamed.push_str(to);
            copied = at + from.len();
        }
    }
    renamed.push_str(&text[copied..]);
    renamed
}

/// The template's crate, by directory prefix: each file whose destination
/// is a `Cargo.toml` — a single-app template's manifest at the root, an
/// App's within a Monorepo template — declares the crate the `.rs` files
/// under it name. A virtual manifest (the monorepo root's `[workspace]`)
/// declares none. Deeper prefixes first, so an App's manifest wins over a
/// root one.
fn declared_crates(files: &[File]) -> Vec<(String, String)> {
    let mut crates: Vec<(String, String)> = files
        .iter()
        .filter_map(|file| {
            let destination = catalog::destination(file.path);
            if std::path::Path::new(destination).file_name() != Some("Cargo.toml".as_ref()) {
                return None;
            }
            let krate = declared_crate(&String::from_utf8_lossy(file.bytes))?;
            let prefix = std::path::Path::new(destination)
                .parent()
                .and_then(|parent| parent.to_str())
                .unwrap_or("")
                .replace('\\', "/");
            Some((prefix, krate))
        })
        .collect();
    crates.sort_by(|a, b| b.0.len().cmp(&a.0.len()).then_with(|| a.0.cmp(&b.0)));
    crates
}

/// Whether `destination` sits under `prefix`: the prefix's own files,
/// when the prefix is the template root (`""`), or the files the prefix's
/// directory holds.
fn under_prefix(destination: &str, prefix: &str) -> bool {
    prefix.is_empty() || destination == prefix || destination.starts_with(&format!("{prefix}/"))
}

/// The crate the manifest `dir`'s directory holds, when it holds one:
/// what the template files copied into that directory must name.
fn crate_under(dir: &Path) -> Option<String> {
    let manifest = std::fs::read_to_string(dir.join("Cargo.toml")).ok()?;
    declared_crate(&manifest)
}

/// The template's files to copy under `dir`, each its path in the project
/// and its contents: all but rok-data-sqlc's generated ones. A text file
/// gets `\n` line endings; a binary one (not UTF-8, such as a web App's
/// `favicon.ico`) is copied byte for byte.
/// When the project's library crate is `krate` and a template subtree's
/// (its `Cargo.toml`'s) another, the Rust files of that subtree name
/// `krate` instead. `names` renames a Monorepo template's Apps after the
/// project (workspace ADR 0027): each text file and path as
/// [`Renames`] says, and each App's Rust files after its renamed crate.
fn plan(
    dir: &Path,
    files: &[File],
    krate: Option<&str>,
    names: &Renames,
) -> Result<Vec<(PathBuf, Vec<u8>)>> {
    let crates = declared_crates(files);
    // The crate an App's manifest declares once renamed.
    let renamed_crate = |prefix: &str| -> Option<String> {
        let manifest = files.iter().find(|file| {
            catalog::destination(file.path) == format!("{prefix}/Cargo.toml").as_str()
        })?;
        let text = String::from_utf8_lossy(manifest.bytes);
        declared_crate(&names.text(manifest.path, &text))
    };
    // Each subtree's rename target: a template root's is the project's
    // crate (`krate`, the crate the project's own manifest declares), an
    // App's within a Monorepo template is the crate the App's manifest
    // already names — when the project holds the manifest, the template's
    // is not copied, and the App's files must name what its manifest
    // declares. A subtree with no existing manifest takes the crate its
    // renamed manifest, copied beside the files, declares.
    let renames: Vec<(String, String, Option<String>)> = crates
        .into_iter()
        .map(|(prefix, from)| {
            let to = if prefix.is_empty() {
                krate.map(str::to_owned)
            } else {
                crate_under(&dir.join(&prefix)).or_else(|| renamed_crate(&prefix))
            };
            (prefix, from, to)
        })
        .collect();
    let renamed = |file: &File| -> Option<(String, String)> {
        let destination = catalog::destination(file.path);
        let (_, from, to) = renames
            .iter()
            .find(|(prefix, _, _)| under_prefix(destination, prefix))?;
        let to = to.as_ref()?;
        (from != to).then(|| (from.clone(), to.clone()))
    };
    let mut planned = Vec::new();
    for file in files {
        let destination = dir.join(names.path(catalog::destination(file.path)).as_ref());
        let Ok(text) = std::str::from_utf8(file.bytes) else {
            planned.push((destination, file.bytes.to_vec()));
            continue;
        };
        let text = text.replace("\r\n", "\n");
        if is_generated(&text) {
            continue;
        }
        // The schema artifact (engine ADR 0010) is generated too, though JSON
        // cannot carry the marker: the template does not ship lone files of
        // `src/db/`, `rok sqlc generate` writes it with the code.
        if catalog::destination(file.path) == "src/db/schema.json" {
            continue;
        }
        let text = names.text(file.path, &text).into_owned();
        let text = match &renamed(file) {
            Some((from, to)) if file.path.ends_with(".rs") => rename_crate(&text, from, to),
            _ => text,
        };
        planned.push((destination, text.into_bytes()));
    }
    Ok(planned)
}

/// The project's name: its directory's, as the user typed it or, for `.`
/// and the like, as the file system resolves it.
fn project_name(dir: &Path) -> String {
    fs::canonicalize(dir)
        .ok()
        .and_then(|dir| {
            dir.file_name()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .or_else(|| {
            dir.file_name()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .unwrap_or_default()
}

/// `--org`'s value parser: `org` when it is a reverse-domain name that can
/// name the Apps, the reason it cannot otherwise (a usage error).
///
/// # Errors
///
/// When `org` would break an Android or iOS identifier.
pub fn parse_org(org: &str) -> std::result::Result<String, String> {
    // Any valid project name will do: only the org is checked.
    Names::new("app", org)
        .map(|names| names.org().to_owned())
        .map_err(|err| err.to_string())
}

/// The names a Monorepo template's Apps take in `dir` under `org` (the
/// default org when `None`); a single-app template takes none, so an
/// `org` for one is an error.
fn names_for(dir: &Path, template: &str, org: Option<&str>) -> Result<Option<Names>> {
    if catalog::apps(template).is_empty() {
        if let Some(org) = org {
            bail!(
                "`--org {org}` names a Monorepo template's Apps; the `{template}` template has none"
            );
        }
        return Ok(None);
    }
    let names = Names::new(&project_name(dir), org.unwrap_or(DEFAULT_ORG))?;
    Ok(Some(names))
}

/// Copies the template `name` into `dir`, keeping every file that exists
/// but cargo's untouched default `src/main.rs`. A Monorepo template's Apps
/// are named after the project (`dir`'s name) and `org` (`com.example`
/// when `None`), workspace ADR 0027.
pub fn init_template(dir: &Path, name: &str, org: Option<&str>) -> Result<Scaffolded> {
    let files = files(name)?;
    let names = names_for(dir, name, org)?;
    let renames = names
        .as_ref()
        .map_or_else(Renames::none, |names| Renames::new(name, names));
    let krate = dir.join("Cargo.toml").is_file().then(|| crate_name(dir));
    let planned = plan(dir, files, krate.as_deref(), &renames)?;
    let main = dir.join("src/main.rs");
    let replaced_default_main = planned.iter().any(|(path, _)| *path == main)
        && fs::read_to_string(&main).is_ok_and(|text| is_cargo_default_main(&text));
    if replaced_default_main {
        fs::remove_file(&main)
            .with_context(|| format!("failed to replace `{}`", display_path(&main)))?;
    }
    let mut written = write_absent(&planned)?;
    // A Monorepo template's Clients are generated, so the copy left them
    // out: they are emitted from the contract the copy wrote (or the one
    // the project holds), each file only when absent, as every file init
    // writes (workspace ADR 0027).
    if let Some(project) = crate::clients::Project::load(&dir.join("rok.toml"))? {
        for outcome in crate::clients::generate(&project, crate::clients::Mode::Absent)? {
            written.extend(outcome.written);
        }
    }
    let manifest = dir.join("Cargo.toml");
    Ok(Scaffolded {
        wrote_manifest: written.contains(&manifest),
        written,
        replaced_default_main,
        api_package: names.map(|names| names.api_package()),
    })
}

